"""
Archival Binder Module R-04
Implements parse_bindings for structured section.key=value configuration lines.
"""


def _split_qualifier_value(stripped_line: str) -> tuple[str, str]:
    """Split a stripped line into (qualifier, value) on the first '='."""
    if "=" not in stripped_line:
        raise ValueError(
            f"Archival field 'line' is malformed (missing '='): {stripped_line!r}"
        )
    equals_index = stripped_line.index("=")
    qualifier_part = stripped_line[:equals_index]
    value_part = stripped_line[equals_index + 1:]
    return qualifier_part, value_part


def _split_section_key(qualifier_part: str, stripped_line: str) -> tuple[str, str]:
    """Split a qualifier string into (section, key) on the first '.'."""
    qualifier_stripped = qualifier_part.strip()
    if "." not in qualifier_stripped:
        raise ValueError(
            f"Archival field 'qualifier' is malformed (missing '.'): {qualifier_stripped!r}"
        )
    dot_index = qualifier_stripped.index(".")
    section = qualifier_stripped[:dot_index].strip()
    key = qualifier_stripped[dot_index + 1:].strip()

    if not section:
        raise ValueError(
            f"Archival field 'section' must not be empty in line: {stripped_line!r}"
        )
    if not key:
        raise ValueError(
            f"Archival field 'key' must not be empty in line: {stripped_line!r}"
        )
    return section, key


def _parse_single_line(stripped_line: str) -> tuple[str, str, str]:
    """Parse a single stripped configuration line into (section, key, value)."""
    qualifier_part, value_part = _split_qualifier_value(stripped_line)
    section, key = _split_section_key(qualifier_part, stripped_line)
    value = value_part.strip()
    return section, key, value


def parse_bindings(lines: list[str]) -> dict[str, dict[str, str]]:
    """
    Parse a list of configuration lines into a nested ordered dictionary.

    Each non-empty, non-comment line must follow the format:
        section.key=value

    Comments begin with '#'. Whitespace around section, key, and value is stripped.
    Input order is preserved in the returned dictionary.

    Raises TypeError if lines is not a list.
    Raises ValueError for:
        - Lines that do not match the expected format
        - Empty section names
        - Empty key names
        - Non-string items in lines
    """
    if not isinstance(lines, list):
        raise TypeError(
            f"parse_bindings expects a list of strings, got {type(lines).__name__!r}"
        )

    bindings_ledger: dict[str, dict[str, str]] = {}

    for index, raw_line in enumerate(lines):
        if not isinstance(raw_line, str):
            raise ValueError(
                f"parse_bindings: all items in 'lines' must be strings; "
                f"item at index {index} is {type(raw_line).__name__!r}"
            )

        stripped_line = raw_line.strip()

        if not stripped_line:
            continue

        if stripped_line.startswith("#"):
            continue

        section, key, value = _parse_single_line(stripped_line)

        if section not in bindings_ledger:
            bindings_ledger[section] = {}

        bindings_ledger[section][key] = value

    return bindings_ledger


def flatten_bindings(bindings: dict[str, dict[str, str]]) -> list[str]:
    """
    Flatten a nested bindings dictionary into a list of "section.key=value" strings.

    Entries are emitted in dictionary iteration order (section order, then key
    order within each section).

    Raises TypeError if bindings is not a dict.
    Raises ValueError if any section value is not a dict, or if any key or
    section name is not a string.
    """
    if not isinstance(bindings, dict):
        raise TypeError(
            f"flatten_bindings expects a dict, got {type(bindings).__name__!r}"
        )

    result: list[str] = []
    for section, pairs in bindings.items():
        if not isinstance(section, str):
            raise ValueError(
                f"flatten_bindings: section names must be strings, "
                f"got {type(section).__name__!r}"
            )
        if not isinstance(pairs, dict):
            raise ValueError(
                f"flatten_bindings: values for each section must be dicts; "
                f"section {section!r} has {type(pairs).__name__!r}"
            )
        for key, value in pairs.items():
            if not isinstance(key, str):
                raise ValueError(
                    f"flatten_bindings: keys must be strings in section {section!r}, "
                    f"got {type(key).__name__!r}"
                )
            if not isinstance(value, str):
                raise ValueError(
                    f"flatten_bindings: values must be strings in section {section!r}, "
                    f"key {key!r} has {type(value).__name__!r}"
                )
            result.append(f"{section}.{key}={value}")
    return result

